export const isAudioRecognitionActivity=activity=>{
  if(['audio_to_kana','listening_choice','minimal_pair'].includes(activity?.type))return true;
  if(!activity?.audio)return false;
  const prompt=String(activity.prompt||'');
  return/forma escrita correcta|letra o símbolo correcto|(?:acabas|acabaste) de escuchar|¿?qué (?:letra|grafema|símbolo|sonido|sílaba|palabra|frase|vocal)\b.*\b(?:escuchas|oyes|oíste)\b/i.test(prompt);
};
export const usesSelectedOptionAudio=activity=>{
  if(activity?.type==='audio_to_kana')return true;
  const prompt=String(activity?.prompt||'');
  return/forma escrita correcta|letra o símbolo correcto|qué (?:letra|grafema|símbolo|sílaba|palabra|frase|vocal)\b.*\b(?:escuchas|oyes|oíste)\b/i.test(prompt);
};
export const isStageOpeningLesson=(course,unit,lesson)=>{
  const firstLesson=(unit?.lessons||[]).find(item=>!item.isReview&&!item.isTest);
  if(!firstLesson||firstLesson.id!==lesson?.id)return false;
  const configured=(course?.levels||[]).filter(level=>Array.isArray(level.unitIds)&&level.unitIds.length);
  if(configured.length)return configured.some(level=>level.unitIds[0]===unit?.id);
  return course?.units?.[0]?.id===unit?.id;
};
export const lessonActivitiesForPresentation=(course,unit,lesson)=>{
  const activities=lesson?.activities||[];
  if(isStageOpeningLesson(course,unit,lesson)||activities[0]?.type!=='lesson_intro')return activities;
  return activities.slice(1);
};
