  async continue(){if(this.activityIndex<this.lesson.activities.length-1){this.activityIndex++;this.feedback=null;this.speechState=null;this.renderActivity();return;}const result=scoreActivities(this.lesson.activities,this.answers,this.language);if(this.reviewMode){this.progress=completeGuidedReview(this.progress,this.reviewItems,result,this.progressConfig());await this.put('metadata',this.progress);this.reviewResult=result;this.reviewMode=false;this.renderReviewResult(result);return;}const lessonConfig=this.progressConfig(this.lesson),passing=lessonConfig.passingScore,passed=result.percentage>=passing;this.progress=completeGuidedLesson(this.progress,this.unit,this.lesson,result,lessonConfig);if(passed){const lessonType=this.lesson.isReview?'review':this.lesson.isTest?'test':this.lesson.isUnitFinal?'unitFinal':'normal',reward=await xpService.awardLessonXP({languageId:this.language,courseId:this.course.courseId||`${this.definition.slug}-from-zero`,lessonId:this.lesson.id,score:result.percentage,completedAt:new Date().toISOString(),lessonType,xpReward:this.lesson.xpReward});result.awardedXp=reward.xp;this.centralXp=xpForLanguage(reward.summary,this.language);}else result.awardedXp=0;const lessonIndex=this.unit.lessons.findIndex(item=>item.id===this.lesson.id),lastLesson=lessonIndex===this.unit.lessons.length-1;if(passed&&lastLesson){const unitIndex=this.course.units.findIndex(item=>item.id===this.unit.id),nextSummary=this.course.units[unitIndex+1],nextUnit=nextSummary&&this.units.get(nextSummary.id);if(nextUnit){if(!this.progress.unlockedUnits.includes(nextUnit.id))this.progress.unlockedUnits.push(nextUnit.id);const first=nextUnit.lessons[0];if(!this.progress.unlockedLessons.includes(first.id))this.progress.unlockedLessons.push(first.id);this.progress.currentUnit=nextUnit.id;this.progress.currentLesson=first.id;}}this.results.set(this.lesson.id,result);await this.put('metadata',this.progress);this.navigate('result',this.lesson.id);}
  renderResult(id){const found=this.findLesson(id);if(!found){this.renderMap();return;}const passing=Number(found.lesson.passingScore??this.course.unlockRules?.minimumScore??GUIDED_PASSING_SCORE),mastery=Number(this.course.unlockRules?.masteryScore||GUIDED_MASTERY_SCORE),result=this.results.get(id)||this.progress.lessonScores[id]||{percentage:0,correct:0,total:found.lesson.activities.length,awardedXp:0,errors:[]},errors=result.errors||[],next=found.unit.lessons[found.unit.lessons.findIndex(item=>item.id===id)+1],passed=result.percentage>=passing,resultLabel=found.lesson.isReview?'REPASO TERMINADO':found.lesson.isTest?'PRUEBA TERMINADA':'LECCIÓN TERMINADA',nextLabel=next?.isReview?'Siguiente repaso':next?.isTest?'Siguiente prueba':'Siguiente lección';this.shell(`<section class="jp-result ${passed?'passed':'retry'}"><div class="jp-result-medal">${result.percentage>=mastery?'★':passed?'✓':'↻'}</div><span class="eyebrow">${resultLabel}</span><h1>${passed?'¡Buen trabajo!':`Necesitas ${passing} % para avanzar`}</h1><div class="jp-result-score"><b>${result.percentage}%</b><span>${result.correct} de ${result.total} correctas</span></div><div class="jp-result-stats"><div><b>+${Number(result.awardedXp||0)}</b><span>XP nuevo</span></div><div><b>${errors.length}</b><span>Para repasar</span></div></div>${errors.length?`<section class="jp-needs-review"><h2>Necesitan repaso</h2>${errors.map(error=>`<span lang="${esc(this.definition.htmlLang)}">${esc(error.activity?.target||error.answer)}</span>`).join('')}</section>`:''}<div class="jp-result-actions">${errors.length?`<button data-jp-action="retry" data-jp-retry="${esc(id)}">Repetir errores</button>`:''}${next&&passed?`<button class="primary" data-jp-lesson="${esc(next.id)}">${nextLabel}</button>`:''}<button data-jp-unit="${esc(found.unit.id)}">Volver a la unidad</button><button data-jp-route="course">Volver al mapa</button></div></section>`,'Resultado');}
