  formatReviewDate(value){return new Date(value).toLocaleDateString('es-MX',{day:'numeric',month:'short'});}
  renderReview(){const schedule=reviewSchedule(this.progress),allowance=this.reviewAllowance(),due=schedule.due.slice(0,Math.min(12,allowance.remaining)),available=Math.min(schedule.due.length,allowance.remaining),percent=Math.round(allowance.completed/allowance.limit*100);this.reviewMode=false;this.shell(`<section class="jp-simple-view jp-review-dashboard"><span class="eyebrow">REPETICIÓN ESPACIADA</span><h1>Repaso de hoy</h1><p>Cada elemento vuelve después de 1, 3, 7, 14 y 30 días. Si fallas, vuelve antes; si aciertas, el intervalo crece.</p><div class="jp-srs-steps"><span>1 día</span><span>3 días</span><span>7 días</span><span>14 días</span><span>30 días</span></div><section class="jp-daily-review-limit"><div><strong>${allowance.completed} de ${allowance.limit}</strong><span>tarjetas repasadas hoy</span></div><div class="jp-progress"><i style="width:${percent}%"></i></div><small>Puedes cambiar este límite en Cuenta → Ajustes.</small></section>${due.length?`<section class="jp-review-ready"><strong>${available}</strong><div><h2>Repaso preparado</h2><p>Las respuestas permanecen ocultas hasta comenzar para que el repaso mida tu memoria de verdad.</p></div></section><button class="primary" data-jp-action="start-review">Comenzar repaso</button>`:`<div class="jp-empty-state"><b>✓</b><h2>${allowance.remaining?'Estás al día':'Límite diario completado'}</h2><p>${allowance.remaining?'Cuando corresponda, se preparará una nueva sesión.':'Buen trabajo. Puedes continuar aprendiendo contenido nuevo sin acumular más repasos hoy.'}</p></div>`}<button data-jp-route="course">Volver al mapa</button></section>`,'Repaso');}
  startReview(){const allowance=this.reviewAllowance(),due=reviewSchedule(this.progress).due.slice(0,Math.min(12,allowance.remaining));if(!due.length)return this.renderReview();this.reviewMode=true;this.reviewItems=due;this.lesson={id:`srs-${Date.now()}`,title:'Repaso espaciado',activities:due.map(item=>item.activity).filter(Boolean)};this.unit={id:'spaced-review',lessons:[this.lesson]};this.activityIndex=0;this.answers={};this.blockSelections={};this.speechState=null;this.feedback=null;this.renderActivity();}
  renderReviewResult(result){const correct=result.correct,total=result.total;this.reviewedToday+=total;const allowance=this.reviewAllowance();this.shell(`<section class="jp-result passed"><div class="jp-result-medal">↻</div><span class="eyebrow">REPASO TERMINADO</span><h1>${correct===total?'¡Todo recordado!':'Tu memoria se está fortaleciendo'}</h1><div class="jp-result-score"><b>${result.percentage}%</b><span>${correct} de ${total} correctas</span></div><p>${result.errors.length?'Lo que fallaste volverá antes. Los aciertos avanzaron al siguiente intervalo.':'Todos los elementos avanzaron al siguiente intervalo.'}</p><p>Hoy llevas <strong>${allowance.completed} de ${allowance.limit}</strong> tarjetas.</p><div class="jp-result-actions"><button class="primary" data-jp-route="review">Volver a repaso</button><button data-jp-route="course">Volver al mapa</button></div></section>`,'Resultado del repaso');}
  renderProfile(){const scores=Object.values(this.progress.lessonScores),accuracy=scores.length?Math.round(scores.reduce((sum,item)=>sum+item.percentage,0)/scores.length):0;this.shell(`<section class="jp-simple-view"><span class="eyebrow">TU AVANCE</span><h1>Perfil de estudio</h1><div class="jp-profile-grid"><div><b>${this.centralXp}</b><span>XP de ${esc(this.definition.name.toLowerCase())}</span></div><div><b>${this.progress.streak}</b><span>Días de racha</span></div><div><b>${this.progress.completedLessons.length}</b><span>Pasos completados</span></div><div><b>${accuracy}%</b><span>Precisión</span></div></div><p>Aquí se muestra únicamente tu XP de ${esc(this.definition.name.toLowerCase())}. La XP global de HanStory continúa disponible en tu cuenta.</p><button data-jp-route="course">Volver al mapa</button></section>`,'Perfil');}
  optionAudioKey(activity,selected){if(!selected)return'';const explicit=activity.option_audio?.[selected]||activity.optionAudio?.[selected];if(explicit)return explicit;const lessonActivities=this.lesson?.activities||[],unitActivities=this.unit?.lessons?.flatMap(lesson=>lesson.activities||[])||[],candidate=[...lessonActivities,...unitActivities].find(item=>item.audio&&String(item.target||item.answer)===String(selected));if(candidate)return candidate.audio;if(String(selected)===String(activity.answer))return activity.audio||'';return this.audioManifest[selected]?selected:'';}
  setAudioButtonState(button,state='idle'){if(!button)return;button.classList.remove('is-loading','is-playing','is-error');button.removeAttribute('aria-busy');if(state==='loading'){button.classList.add('is-loading');button.setAttribute('aria-busy','true');}else if(state==='playing'){button.classList.add('is-playing');button.setAttribute('aria-busy','true');}else if(state==='error'){button.classList.add('is-error');setTimeout(()=>button.classList.remove('is-error'),900);}}
  async playAudio(mode='normal',source='prompt',button=null){const activity=this.lesson?.activities[this.activityIndex];if(!activity)return;let key=button?.dataset.jpAudioKey||'';if(!key&&source==='selection'){const selected=this.answers[activity.id]||'';if(!selected){this.setAudioButtonState(button,'error');this.showToast('Selecciona primero una opción para escucharla.');return;}key=this.optionAudioKey(activity,selected);if(!key){this.setAudioButtonState(button,'error');this.showToast(`Todavía no hay audio asociado a «${selected}».`);return;}}else if(!key)key=mode==='slow'?(activity.slow_audio||activity.audio):activity.audio;const ok=await this.playKeyAudio(key,mode,true,state=>this.setAudioButtonState(button,state));this.setAudioButtonState(button,ok?'idle':'error');}
