  async playKeyAudio(key,mode='normal',notify=true,onState=null){const path=this.audioManifest[key];if(!path){onState?.('error');if(notify)this.showToast(`El audio completo de «${key}» está pendiente en HanStory Studio.`);return false;}const repeat=mode==='repeat'?3:1,rate=mode==='slow'?.65:1;for(let round=0;round<repeat;round++){const ok=await this.playFile(path,rate,onState);if(!ok)return false;}return true;}
  playFile(path,rate,onState=null){return new Promise(resolve=>{this.audio.pause();this.audio.src=this.url(`library/courses/${this.definition.directory}/${path}`);this.audio.playbackRate=rate;let finished=false;const done=ok=>{if(finished)return;finished=true;resolve(ok);};onState?.('loading');this.audio.onplaying=()=>onState?.('playing');this.audio.onended=()=>done(true);this.audio.onerror=()=>done(false);this.audio.play().catch(()=>done(false));});}
